(() => {
  const controls = document.querySelector('.language-switch');
  const buttons = [...controls.querySelectorAll('button[data-language]')];
  const elements = [...document.querySelectorAll('[data-i18n]')];
  const originals = new Map(elements.map(element => [element, {
    html: element.innerHTML,
    lang: element.getAttribute('lang')
  }]));
  const title = document.title;
  const description = document.querySelector('meta[name="description"]');
  const originalDescription = description.content;
  const portrait = document.querySelector('.portrait img');
  const originalAlt = portrait.alt;
  const navigation = document.querySelector('nav');
  const profiles = document.querySelector('.intro .profile-links');
  const englishOnly = [...document.querySelectorAll('[data-language-only="en"]')];
  const storageKey = 'cecilia-site-language';

  function setLanguage(language, remember = false) {
    const isChinese = language === 'zh-CN';
    const selected = isChinese ? 'zh-CN' : 'en';
    for (const element of elements) {
      const original = originals.get(element);
      // Both language versions are trusted text maintained in this project.
      const bilingualTitle = element.matches('.publication h3, .working-papers h4');
      if (isChinese && bilingualTitle) {
        element.innerHTML = original.html;
        const translation = document.createElement('span');
        translation.className = 'paper-translation';
        translation.lang = 'zh-CN';
        translation.textContent = chineseTranslations[element.dataset.i18n];
        element.append(translation);
      } else {
        element.innerHTML = isChinese ? chineseTranslations[element.dataset.i18n] : original.html;
      }
      if (isChinese && !bilingualTitle) element.setAttribute('lang', 'zh-CN');
      else if (original.lang !== null) element.setAttribute('lang', original.lang);
      else element.removeAttribute('lang');
    }
    document.documentElement.lang = selected;
    englishOnly.forEach(element => { element.hidden = isChinese; });
    document.title = isChinese ? '沈梁麒 · 个人学术主页' : title;
    description.content = isChinese
      ? '沈梁麒，多伦多大学社会工作博士生，从生命历程视角研究残障、家庭照护与健康。'
      : originalDescription;
    portrait.alt = isChinese ? '沈梁麒在鲜花环绕的温室中' : originalAlt;
    navigation.setAttribute('aria-label', isChinese ? '主导航' : 'Main navigation');
    profiles.setAttribute('aria-label', isChinese ? '学术与职业主页' : 'Academic and professional profiles');
    buttons.forEach(button => button.setAttribute('aria-pressed', String(button.dataset.language === selected)));
    if (remember) {
      try { localStorage.setItem(storageKey, selected); } catch { /* Switching also works without storage access. */ }
      try {
        const url = new URL(location.href);
        url.searchParams.set('lang', selected);
        if (url.hash === '#chinese-introduction') url.hash = '#about';
        history.replaceState(null, '', url);
      } catch { /* Local file previews can restrict History API access. */ }
    }
  }

  const requested = new URLSearchParams(location.search).get('lang');
  let initial = requested === 'zh' || requested === 'zh-CN' ? 'zh-CN' : requested === 'en' ? 'en' : null;
  if (initial === null) {
    try { initial = localStorage.getItem(storageKey); } catch { /* English remains the default. */ }
  }
  setLanguage(initial === 'zh-CN' ? 'zh-CN' : 'en');
  controls.hidden = false;
  controls.addEventListener('click', event => {
    const button = event.target.closest('button[data-language]');
    if (button) setLanguage(button.dataset.language, true);
  });
})();
